aarav_quiz_schema_next_question.json.content:
{
  "type": "OBJECT",
  "properties": {
    "done": {
      "type": "BOOLEAN",
      "description": "true to terminate quiz, false to continue"
    },
    "questionType": {
      "type": "STRING",
      "format": "enum",
      "enum": [
        "standard",
        "listen-prompt",
        "voice-answer"
      ]
    },
    "prompt": {
      "type": "STRING",
      "description": "Full question text for logging"
    },
    "displayPrompt": {
      "type": "STRING",
      "description": "Text shown on screen"
    },
    "listenText": {
      "type": "STRING",
      "description": "Word/phrase spoken aloud for listen-prompt; empty otherwise"
    },
    "options": {
      "type": "ARRAY",
      "items": {
        "type": "STRING"
      },
      "description": "Exactly 4 answer options"
    },
    "correctIndex": {
      "type": "INTEGER",
      "description": "0-based index of correct option (0-3)"
    },
    "correctAnswer": {
      "type": "STRING",
      "description": "The exact text of the correct option (must match one of the options array entries)"
    },
    "difficulty": {
      "type": "INTEGER",
      "description": "Difficulty 1-100"
    },
    "topic": {
      "type": "STRING",
      "description": "Topic tag for dedup"
    }
  },
  "required": [
    "done"
  ]
}

aarav_tutor_schema_ask_aarav.json.content:
{
  "type": "OBJECT",
  "properties": {
    "speech": {
      "type": "STRING",
      "description": "What Aarav says aloud"
    },
    "end_session": {
      "type": "BOOLEAN",
      "description": "true to end session"
    },
    "quick_replies": {
      "type": "ARRAY",
      "items": {
        "type": "STRING"
      },
      "description": "Suggested reply chips"
    },
    "ui": {
      "type": "OBJECT",
      "description": "Visual activity block. MUST always be present with an explicit type. Use none for conversational turns. Use cue_card when asking child to identify/name/describe something visual. Use choices for grammar/vocabulary checks. Use word_builder for sentence assembly.",
      "required": [
        "type"
      ],
      "properties": {
        "type": {
          "type": "STRING",
          "format": "enum",
          "enum": [
            "none",
            "cue_card",
            "choices",
            "word_builder"
          ],
          "description": "none = no visual activity this turn. cue_card/choices/word_builder = show activity. You MUST use cue_card when asking to identify or name something."
        },
        "emoji": {
          "type": "STRING",
          "description": "Required for cue_card: big emoji shown on screen (e.g. cricket bat emoji)"
        },
        "label": {
          "type": "STRING",
          "description": "Required for cue_card: text label under emoji (e.g. Cricket Bat)"
        },
        "prompt": {
          "type": "STRING",
          "description": "For cue_card: optional question text shown below the card"
        },
        "options": {
          "type": "ARRAY",
          "items": {
            "type": "STRING"
          },
          "description": "Required for choices: 2-4 answer options"
        },
        "correct": {
          "type": "INTEGER",
          "description": "Required for choices: 0-based index of correct option"
        },
        "words": {
          "type": "ARRAY",
          "items": {
            "type": "STRING"
          },
          "description": "Required for word_builder: shuffled word chips for sentence assembly"
        }
      }
    },
    "level_update": {
      "type": "OBJECT",
      "nullable": true,
      "properties": {
        "en": {
          "type": "INTEGER",
          "nullable": true
        },
        "hi": {
          "type": "INTEGER",
          "nullable": true
        },
        "pa": {
          "type": "INTEGER",
          "nullable": true
        }
      }
    }
  },
  "required": [
    "speech",
    "ui"
  ]
}

aarav_tutor_schema_session_summary.json.content:
{
  "type": "OBJECT",
  "properties": {
    "summary": {
      "type": "STRING",
      "description": "1-2 sentences on what was practised, struggles, and wins in this session's language"
    },
    "general": {
      "type": "STRING",
      "description": "1 sentence on mood/energy/interests"
    },
    "topics": {
      "type": "ARRAY",
      "items": {
        "type": "STRING"
      },
      "description": "Up to 5 topic keywords from this session"
    },
    "aiLevel": {
      "type": "INTEGER",
      "description": "Estimated proficiency 0-100 for the language practiced in this session"
    }
  },
  "required": [
    "summary",
    "general",
    "topics",
    "aiLevel"
  ]
}
